declare(strict_types=1);namespace Inilim\Tool\Method\Exp{function excelGenerateCellRange(string $range):\Generator{if(!\Inilim\Tool\Method\Str\isMatch('/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/i',$range)){throw new \InvalidArgumentException("Неверный формат диапазона: {$range} Пример: A1:C10");}$anonObj=new class{function __invoke(string $range):\Generator{$range=\strtoupper($range);\preg_match('/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/',$range,$matches);$startCol=$matches[1];$startRow=(int) $matches[2];$endCol=$matches[3];$endRow=(int) $matches[4];for($row=$startRow;$row<=$endRow;$row++){foreach($this -> generateColumnsBetween($startCol,$endCol)as $column){yield $column.$row;}}}function generateColumnsBetween(string $start,string $end):\Generator{$current=$start;while($current<=$end){yield $current;$current=$this -> incrementColumn($current);if($current===$start){break;}}}function incrementColumn(string $column):string{$chars=\str_split(\strrev($column));$carry=true;$result='';foreach($chars as $char){if($carry){if($char==='Z'){$result .= 'A';$carry=true;}else{$result .= \chr(\ord($char)+1);$carry=false;}}else{$result .= $char;}}if($carry){$result .= 'A';}return \strrev($result);}};return $anonObj -> __invoke($range);}}namespace Inilim\Tool\Method\Str{if(!\Inilim\Tool\Str::__definedIfNot('isMatch')){
    function isMatch($pattern,string $value):bool{if(!\is_iterable($pattern)){$pattern=[$pattern];}foreach($pattern as $pattern){if(\preg_match((string) $pattern,$value)===1){return true;}}return false;}
